import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
import { parseResponse } from "./offset-commit-v0.js";
export { parseResponse };
/*
  OffsetCommit Request (Version: 2) => group_id generation_id member_id retention_time_ms [topics]
    group_id => STRING
    generation_id => INT32
    member_id => STRING
    retention_time_ms => INT64
    topics => name [partitions]
      name => STRING
      partitions => partition_index committed_offset metadata
        partition_index => INT32
        committed_offset => INT64
        metadata => NULLABLE_STRING
*/
export function createRequest(groupId, generationId, memberId, _groupInstanceId, topics) {
    return Writer.create()
        .appendString(groupId, false)
        .appendInt32(generationId)
        .appendString(memberId ?? '', false)
        .appendInt64(-1n)
        .appendArray(topics, (w, topic) => {
        w.appendString(topic.name, false).appendArray(topic.partitions, (w, partition) => w
            .appendInt32(partition.partitionIndex)
            .appendInt64(partition.committedOffset)
            .appendString(partition.committedMetadata, false), false, false);
    }, false, false);
}
export const api = createAPI(8, 2, createRequest, parseResponse, false, false);
